// (b) を単純にここで active へ戻してしまうと、案 B（復元時に deleting を
// 同期的に active へ戻す）を却下した理由そのもの ——「active なのにファイルが
// 無い行」を作ってしまう。この SELECT + Go 側の stat + 分岐は、その窓を
// revert 経路自身に持ち込まないための構成。
func (q *Queries) ListUnqualifiedDeletingAssets(ctx context.Context, arg ListUnqualifiedDeletingAssetsParams) ([]ListUnqualifiedDeletingAssetsRow, error) {
	rows, err := q.db.Query(ctx, listUnqualifiedDeletingAssets,
		arg.StoreName,
		arg.GraceCutoff,
		arg.DesiredStore,
		arg.OverlapCutoff,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUnqualifiedDeletingAssetsRow
	for rows.Next() {
		var i ListUnqualifiedDeletingAssetsRow
		if err := rows.Scan(
			&i.CopyID,
			&i.MediaAssetID,
			&i.RecordingID,
			&i.RelPath,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

