const markPurgedRecordings = `-- name: MarkPurgedRecordings :many
UPDATE recordings r
SET purged_at = now(), updated_at = now()
WHERE r.purged_at IS NULL
  AND EXISTS (
    SELECT 1 FROM trash_deletable_recordings($1::timestamptz) t
    WHERE t.recording_id = r.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM media_assets a
    WHERE a.recording_id = r.id
      AND EXISTS (
          SELECT 1 FROM media_asset_copies copy
          WHERE copy.media_asset_id = a.id AND copy.state <> 'deleted'
      )
  )
RETURNING r.id, r.site, r.title
`

type MarkPurgedRecordingsRow struct {
	ID    int64
	Site  string
	Title string
}

// 「完全削除が完了した」という不可逆な事実を確定する（issue #135）。
//
// 削除 reconcile のパス末尾（trash / until_encoded / pending 経路すべてが
// 物理 unlink を終えた後）で 1 回だけ呼ぶ。ごみ箱条件は名前付き述語
// trash_deletable_recordings への参照（issue #160）。即時削除の要求だけを
// 条件にすると、30 日猶予超過の経路（要求の行が無いまま完全削除に到達する）を
// 拾い損なう —— この区別は述語の定義側に集約されている。
//
// recordings を起点に引く（media_assets を起点にすると、アセットを 1 行も
// 持ったことがない録画が NOT EXISTS の対象になりようがなく、永久に拾えない。
// issue #135 の実測 id 6/7/10/86 がこのケース）。判定は「state <> 'deleted'
// のコピーが 1 つもない」であって「media_assets が 0 行」ではない
// （NOT EXISTS は両方を等しく真にするので実装上は同じ式になるが、意図は
// 前者 —— deleting は「消えた」に数えない。deleting はまだ unlink 待ちで、
// issue #105 の経路で active に戻りうる）。
//
// purged_at IS NULL を条件にも RETURNING にも使うことで、同じ録画を複数パスで
// 数え直さない（冪等）。呼び出し側はこの結果をそのまま recording.deleted の
// 発火対象にできる —— この WHERE が「発火してよい」の判定そのものであり、
// 通知の瞬間に別途 EXISTS を計算して捨てる必要がない（旧 GetRecordingPurgeState
// はこの計算を通知直前に行って結果を保存しなかったため、対象になる録画の
// 集合そのものが存在しないという根本原因を残していた）。
func (q *Queries) MarkPurgedRecordings(ctx context.Context, graceCutoff time.Time) ([]MarkPurgedRecordingsRow, error) {
	rows, err := q.db.Query(ctx, markPurgedRecordings, graceCutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MarkPurgedRecordingsRow
	for rows.Next() {
		var i MarkPurgedRecordingsRow
		if err := rows.Scan(&i.ID, &i.Site, &i.Title); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markUntilEncodedOriginalCopyDeleting = `-- name: MarkUntilEncodedOriginalCopyDeleting :execrows
UPDATE media_asset_copies copy
SET state = 'deleting', deleted_at = NULL
FROM media_assets a
WHERE copy.id = $1
  AND copy.media_asset_id = a.id
  AND a.id = $2
  AND copy.store = $3
  AND copy.state = 'active'
  AND EXISTS (
      SELECT 1 FROM until_encoded_deletable_originals($4::text) AS v(asset_id, recording_id)
      WHERE v.asset_id = $2
  )
`

type MarkUntilEncodedOriginalCopyDeletingParams struct {
	CopyID       int64
	AssetID      int64
	StoreName    string
	DesiredStore *string
}

// until_encoded の候補は列挙後に利用者の再作成要求が追加されうるため、録画行を
// ロックした tx 内で資格を再評価してから deleting にする。API の要求書き込みも
// 同じ recordings 行を先にロックするため、要求の commit と原本削除は直列化される。
func (q *Queries) MarkUntilEncodedOriginalCopyDeleting(ctx context.Context, arg MarkUntilEncodedOriginalCopyDeletingParams) (int64, error) {
	result, err := q.db.Exec(ctx, markUntilEncodedOriginalCopyDeleting,
		arg.CopyID,
		arg.AssetID,
		arg.StoreName,
		arg.DesiredStore,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revertMediaAssetCopyToActive = `-- name: RevertMediaAssetCopyToActive :execrows
UPDATE media_asset_copies copy
SET state = 'active', deleted_at = NULL
FROM media_assets a
WHERE copy.id = $1
  AND copy.store = $2
  AND a.id = copy.media_asset_id
  AND copy.state = 'deleting'
  AND NOT EXISTS (
      SELECT 1 FROM trash_deletable_recordings($3::timestamptz) t
      WHERE t.recording_id = a.recording_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM until_encoded_deletable_originals($4::text) AS v(asset_id, recording_id)
    WHERE v.asset_id = a.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM removed_encoded_assets x WHERE x.asset_id = a.id
  )
  AND NOT EXISTS (
      SELECT 1
      FROM old_generation_media_asset_copies AS old_copy
      WHERE old_copy.id = copy.id
        AND old_copy.generation_started_at <= $5::timestamptz
  )
`

type RevertMediaAssetCopyToActiveParams struct {
	CopyID        int64
	StoreName     string
	GraceCutoff   time.Time
	DesiredStore  *string
	OverlapCutoff time.Time
}

// ListUnqualifiedDeletingAssets が挙げた 1 行を active に戻す。ファイルが
// まだ存在すると Go 側で確認できたときだけ呼ぶこと。
//
// WHERE に同じ判定条件（名前付き述語）を再度埋め込み、事前の
// SELECT の結果（真偽値）を受け渡さずこの UPDATE 自体の瞬間に再評価する
// （不変条件 9「適用の瞬間」）。SELECT から数行の Go コードを挟むだけの短い
// 窓だが、その間に別の書き手（RestoreRecording・encode_profiles 変更 API 等）
// が recordings 側を書き換えて再度条件を満たすようになっていれば、ここで
// 0 行になり active には戻らない（= 正しく deleting のまま残り、pending
// 経路が続行する）。
//
// ここで active に戻すのは deleting → active の遷移のみで、進行中の unlink
// とは競合しない: このワーカー自身が copy.state の唯一の書き手
// （InsertOpts の UniqueOpts により同時に 1 パスしか走らない）であり、
// deleting のまま次パスに持ち越された行は前パスのプロセスが既に終了して
// いるので、いま unlink が進行中の行と衝突しようがない。復元 API から
// deleting → active へ即座に戻す案を採らなかったのはこの前提が無い
// （進行中の unlink と非同期に競合しうる）ため。
func (q *Queries) RevertMediaAssetCopyToActive(ctx context.Context, arg RevertMediaAssetCopyToActiveParams) (int64, error) {
	result, err := q.db.Exec(ctx, revertMediaAssetCopyToActive,
		arg.CopyID,
		arg.StoreName,
		arg.GraceCutoff,
		arg.DesiredStore,
		arg.OverlapCutoff,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

